package com.example.notes.core.domain;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class NoteTest {
    @Test
    void create_whenTextIsPresent_returnsNote() {
        Note note = Note.create("text");

        assertThat(note.text()).isEqualTo("text");
    }

    @Test
    @DisplayName("BR-001: Пустой text отклоняется")
    void create_whenTextIsEmpty_throwsException() {
        assertThatThrownBy(() -> Note.create(""))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessage("NOTE_TEXT_EMPTY");
    }
}
